                  "// Uma conexão nova por pedido",
                  "const agentWithoutReuse = new http.Agent({ keepAlive: false });",
                  "",
                  "// A mesma conexão é reaproveitada entre os pedidos",
                  "const agentWithReuse = new http.Agent({ keepAlive: true });",
                  "",
