                  "",
                  "  async create(data) {",
                  "    const id = randomBytes(32).toString(\"hex\");",
                  "    await this.redis.set(`sessao:${id}`, JSON.stringify(data), { EX: this.idleSeconds });",
                  "    return id;",
                  "  }",
                  "",
                  "  async get(id) {",
                  "    const value = await this.redis.get(`sessao:${id}`);",
                  "    if (!value) return null;",
