                  "",
                  "const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();",
                  "let buffer = \"\";",
                  "",
                  "while (true) {",
                  "  const { done, value } = await reader.read();",
                  "  if (done) break;",
                  "",
                  "  buffer += value;",
                  "  const events = buffer.split(\"\\n\\n\");   // um evento termina em uma linha em branco",
