                  "const page1 = items.slice(0, 2);   // [\"E\", \"D\"]",
                  "",
                  "// Enquanto o cliente lê a página 1, chega um item novo no topo",
                  "items = [\"F\", ...items];          // [\"F\", \"E\", \"D\", \"C\", \"B\", \"A\"]",
                  "",
                  "const page2 = items.slice(2, 4);   // [\"D\", \"C\"]  ← \"D\" apareceu de novo",
