                "",
                "db.exec(`",
                "  CREATE TABLE products (",
                "    id INTEGER PRIMARY KEY,",
                "    name TEXT NOT NULL,",
                "    price_cents INTEGER NOT NULL,        -- dinheiro em centavos, sem ponto flutuante",
