                  "",
                  "class Post {",
                  "  constructor(row) { Object.assign(this, row); }",
                  "  get author() {   // \"lazy loading\": busca quando alguém lê a propriedade",
                  "    return query(\"SELECT name FROM authors WHERE id = ?\", this.author_id)[0];",
                  "  }",
