                "  let inUse = 0;",
                "  const waiting = [];",
                "  return {",
                "    get inUse() { return inUse; },",
                "    async acquire() {",
                "      if (inUse < max) { inUse++; return { release: () => this.release() }; }",
                "      return new Promise((resolve, reject) => {",
                "        const timer = setTimeout(() => reject(new Error(\"timeout esperando conexão\")), timeoutMs);",
