                "const db = new Map([[1, { id: 1, name: \"Caneca\", priceCents: 3500 }]]);",
                "",
                "function getProduct(id) {",
                "  if (cache.has(`product:${id}`)) return cache.get(`product:${id}`);",
                "  const product = db.get(id);",
                "  cache.set(`product:${id}`, product);",
                "  return product;",
