                "const redis = await createClient({ url: \"redis://localhost:6379\" }).connect();",
                "",
                "// String com expiração: o uso de cache",
                "await redis.set(\"product:1\", JSON.stringify({ name: \"Caneca\" }), { EX: 600 });",
