                  "  return [keys.current, keys.previous].filter(Boolean).some((key) => {",
                  "    const expected = Buffer.from(sign(value, key));",
                  "    const got = Buffer.from(signature);",
                  "    return expected.length === got.length && timingSafeEqual(expected, got);",
                  "  });",
