                  "const INDEX_KEY = Buffer.alloc(32, 7);   // no exemplo; em produção, do KMS, separada da de cifragem",
                  "const blindIndex = (cpf) => createHmac(\"sha256\", INDEX_KEY).update(cpf.replace(/\\D/g, \"\")).digest(\"hex\");",
